  await change('[data-motion-stream-count]','2',2);await page.click('[data-motion-library-tab="elements"]');await page.click('[data-motion-layer="'+start[0].id+'"]');assert.equal(await page.$eval('[data-motion-element-remove]',n=>n.disabled),true);await change('[data-motion-stream-count]','10',10);await page.click('[data-motion-layer="'+start[0].id+'"]');assert.equal(await page.$eval('[data-motion-duplicate]',n=>n.disabled),true);await change('[data-motion-stream-count]','4');assert.deepEqual((await pose(0)).map(n=>[n.id,n.src]),start.map(n=>[n.id,n.src]));await page.click('[data-motion-layer="'+start[0].id+'"]');assert.equal(await page.$eval('[data-motion-duplicate]',n=>n.disabled),false);
  await change('[data-motion-stream="cardRatio"]','1:1');await change('[data-motion-stream="hold"]','30');await change('[data-motion-stream="shadow"]',false);await change('[data-motion-stream="backgroundType"]','none');await change('[data-motion-stream="cornerRadius"]','0');
