  await page.waitForFunction(()=>Array.from(document.querySelector('.nw-motion-dialog iframe').contentDocument.querySelectorAll('[data-nw-stream-slot] img')).every(img=>img.complete&&img.naturalWidth===320));await pose(.2/4);
  const probes=await page.$eval('.nw-motion-dialog iframe',f=>{const d=f.contentDocument,nodes=Array.from(d.querySelectorAll('[data-nw-stream-slot]')),front=nodes[0],back=nodes[3],host=front.offsetParent,r=front.__nwMotionRoundClip.rect,radius=front.__nwMotionRoundClip.radius,points=[{x:host.clientWidth/2,y:host.clientHeight/2,source:front,color:[255,0,0]},{x:r.left+radius*.1,y:r.top+radius*.1,source:back,color:[255,255,0]}],fr=f.getBoundingClientRect(),hr=host.getBoundingClientRect();return points.map(p=>{const c=p.source.querySelector('.nw-burst-card'),x=p.x-parseFloat(p.source.style.left),y=p.y-parseFloat(p.source.style.top);return{id:p.source.dataset.id,x:fr.left+(hr.left+p.x)*fr.width/f.clientWidth,y:fr.top+(hr.top+p.y)*fr.height/f.clientHeight,pixel:Array.from(c.getContext('2d').getImageData(Math.floor(x*c.width/parseFloat(p.source.style.width)),Math.floor(y*c.height/parseFloat(p.source.style.height)),1,1).data),color:p.color};});});
  for(const point of probes){for(let i=0;i<3;i++)assert.ok(Math.abs(point.pixel[i]-point.color[i])<5);await page.mouse.click(point.x,point.y);assert.equal(await page.$eval('[data-motion-layer="'+point.id+'"]',n=>n.getAttribute('aria-pressed')),'true');}
  await change('[data-motion-stream="cornerRadius"]','0');await page.click('[data-motion-layer="'+start[0].id+'"]');
  // Cover-crop pixels test the horizontal and vertical segment rasterizers with real source files.
